130	func TestExportSnapshotsConcurrentCreate(t *testing.T) {
131		s, err := app.Open("")
132		if err != nil {
133			t.Fatal(err)
134		}
135		defer func() { _ = s.Close() }()
136	
137		doc := "doc-conc"
138		// Seed 400 changes so snapshots can be stored at cursors 1..400.
139		ids := make([]string, 400)
140		for i := range ids {
141			ids[i] = fmt.Sprintf("c%d", i+1)
142		}
143		if _, err := s.PostChanges(doc, changes(ids...)); err != nil {
144			t.Fatal(err)
145		}
146	
147		const writers = 8
148		var wg sync.WaitGroup
149		wg.Add(writers)
150		for w := 0; w < writers; w++ {
151			go func(base int64) {
152				defer wg.Done()
153				for i := int64(0); i < 50; i++ {
154					cursor := base + i // writers claim disjoint cursor windows
155					if _, err := s.PutSnapshot(doc, cursor,
156						json.RawMessage(fmt.Sprintf(`{"w":%d}`, cursor))); err != nil {
157						t.Errorf("put %d: %v", cursor, err)
158						return
159					}
160				}
161			}(int64(w)*50 + 1)
162		}
163	
164		// Concurrently export the whole range repeatedly. Every result must be a
165		// self-consistent set: ascending, unique cursors, and each present row
166		// complete. Counts can differ between runs (commits land in between), but
167		// no half row can ever appear because each row is one committed INSERT
